<template><div class="space-y-4"><el-upload drag multiple accept="image/*" :auto-upload="false" :on-change="addFiles"><el-icon class="el-icon--upload"><UploadFilled/></el-icon><div>拖拽或选择图片</div></el-upload><div class="grid gap-3 md:grid-cols-2"><el-input-number v-model="width" :min="1" placeholder="宽度"/><el-input-number v-model="height" :min="1" placeholder="高度"/><el-checkbox v-model="keepRatio">保持比例</el-checkbox></div><el-button type="primary" size="small" :disabled="!files.length" @click="resize">批量调整并下载</el-button></div></template>
<script setup lang="ts">import { ref } from 'vue';import { UploadFilled } from '@element-plus/icons-vue';import { ElMessage } from 'element-plus';const files=ref<File[]>([]);const width=ref(800);const height=ref(600);const keepRatio=ref(true);const addFiles=(f:any)=>{if(f.raw)files.value.push(f.raw)};const resize=()=>files.value.forEach(file=>{const img=new Image();img.onload=()=>{const w=width.value,h=keepRatio.value?Math.round(img.height*w/img.width):height.value;const c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d')!.drawImage(img,0,0,w,h);c.toBlob(b=>{if(!b)return;const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=`resized-${file.name}`;a.click()},file.type)},img.src=URL.createObjectURL(file)});ElMessage.success(`已处理 ${files.value.length} 张图片`)</script>
